     or public.live_decor_ok('{"table":{"url":"https://x.test/a.png","name":"x"}}') or public.live_decor_ok('{"av_l1":{"url":"https://x.test/a.png","name":"<b>x</b>"}}') or public.live_decor_ok('{"av_l1":{"url":"//evil.test/a.png"}}') or public.live_decor_ok('{"table":{"url":"https://x.test/a.png","x":5}}') or public.live_decor_ok('{"table":{"url":"https://x.test/a.png","x":99,"z":0}}') or public.live_decor_ok('{"table":{"url":"https://x.test/a.png","mirror":true}}') or public.live_decor_ok('{"av_l1":{"url":"https://x.test/a.png","x":1,"z":1}}') then raise exception 'avatar tidak valid diterima'; end if;
  if exists (select 1 from public.live_venues v, jsonb_each(v.decor) e where jsonb_typeof(v.decor) = 'object' and e.key not like 'av\_%' and jsonb_typeof(e.value) = 'object' and v.key not in ('pramuka', 'rups', 'anniversary', 'grandopening', 'sumpahpemuda', 'nyepi', 'iduladha', 'halalbihalal', 'isramikraj', 'guru', 'legoland', 'bukapuasa', 'rustic-wedding', 'pinkparadise', 'littlescientist', 'robotfactory', 'tamanperi', 'jurassic', 'esport', 'cosplay', 'charityrun', 'aksimhs', 'jazznight', 'seminar', 'worldtour', 'gothic', 'dayak', 'sunda', 'gorontalo', 'lebaran', 'wabisabi', 'joseon', 'observatory', 'secretgarden', 'mediterania', 'jepang', 'goldenanniv', 'probation', 'babyshower', 'khitan', 'kelahiran', 'babygirl', 'farewell', 'lamaran', 'istana', 'autumn', 'orient', 'eropa', 'lotus', 'luxury', 'sculpt', 'greenhouse', 'coquette', 'disco', 'opalite', 'carousel', 'littlechef', 'kittycuddles', 'kerajaanlaut', 'princessroyal', 'enchantedrose', 'tangledlantern', 'moana', 'unicorn', 'demonhunter') and (e.value ? 'x' or e.value ? 'z' or e.value ? 'mirror' or (e.key <> 'easel' and v.key not in ('hardiknas', 'kemerdekaan-17-agustus', 'kartini-day', 'adat-melayu-riau') and e.value ? 'w'))) then raise exception 'dekor venue belum memakai tata letak Romantic Garden'; end if;
